// Regression tests generated by the BugRep Test Agent
const { calculateTotal } = require('../src/cart');

describe('calculateTotal — checkout pricing', () => {
  test('coupon above 100% never produces a negative total', () => {
    expect(calculateTotal([{ price: 10 }], 200)).toBe(0);
  });

  test('empty cart with a coupon returns exactly 0', () => {
    expect(calculateTotal([], 10)).toBe(0);
  });

  test('two $50 items with 10% off returns 90', () => {
    expect(calculateTotal([{ price: 50 }, { price: 50 }], 10)).toBe(90);
  });

  test('missing discount is treated as 0%', () => {
    expect(calculateTotal([{ price: 80 }])).toBe(80);
  });

  test('negative discount is clamped to 0% (no surcharge)', () => {
    expect(calculateTotal([{ price: 100 }], -20)).toBe(100);
  });

  test('NaN or Infinity discount throws RangeError', () => {
    expect(() => calculateTotal([{ price: 50 }], NaN)).toThrow(RangeError);
    expect(() => calculateTotal([{ price: 50 }], Infinity)).toThrow(RangeError);
  });

  test('item with a missing or negative price throws TypeError', () => {
    expect(() => calculateTotal([{ name: 'widget' }], 10)).toThrow(TypeError);
    expect(() => calculateTotal([{ price: -5 }], 10)).toThrow(TypeError);
  });

  test('totals are rounded to 2 decimal places', () => {
    expect(calculateTotal([{ price: 0.1 }, { price: 0.2 }], 0)).toBe(0.3);
    expect(calculateTotal([{ price: 10 }], 33.333)).toBe(6.67);
  });
});

