// src/cart.js
// Reset to buggy baseline for this demo run.

/**
 * Calculate the total for a cart after a percentage discount.
 * @param {Array<{price:number}>} items
 * @param {number} [discountPercentage=0]
 * @returns {number} total rounded to 2 decimals, never below 0
 */
function calculateTotal(items, discountPercentage) {
  // Rule 4: missing discount means 0%
  if (discountPercentage === undefined || discountPercentage === null) discountPercentage = 0;

  // Rule 6: NaN / Infinity are programming errors
  if (typeof discountPercentage !== 'number' || !Number.isFinite(discountPercentage)) {
    throw new RangeError(`discountPercentage must be a finite number, got ${discountPercentage}`);
  }

  // Rule 5: a discount can never act as a surcharge
  if (discountPercentage < 0) discountPercentage = 0;

  // Rule 3: empty cart is always 0
  if (!Array.isArray(items) || items.length === 0) return 0;

  // Rules 7 & 8: every price must be a finite, non-negative number
  for (const item of items) {
    const p = item && item.price;
    if (typeof p !== 'number' || !Number.isFinite(p) || p < 0) {
      throw new TypeError(`Invalid item price: ${p}`);
    }
  }

  let subtotal = items.reduce((sum, item) => sum + item.price, 0);
  let discount = (subtotal * discountPercentage) / 100;

  // Rule 2: never below 0; Rule 9: round to 2 decimals
  return Math.round(Math.max(0, subtotal - discount) * 100) / 100;
}

module.exports = { calculateTotal };
